import type { SQL } from "bun";
import { drizzle } from "drizzle-orm/bun-sql";
import { migrate as drizzleMigrate } from "drizzle-orm/bun-sql/migrator";

/*
 * Generated by drizzle-kit from schema.ts. Resolved from the working
 * directory, so run the server from the project root.
 */
export const MIGRATIONS_FOLDER = "drizzle";

export const migrate = (sql: SQL, migrationsFolder = MIGRATIONS_FOLDER) =>
  drizzleMigrate(drizzle({ client: sql }), { migrationsFolder });
